function toBaseSeven(num: number): string {
  if (num === 0) return "0";
  let n = Math.abs(num);
  const digits: number[] = [];
  while (n > 0) {
    digits.push(n % 7);
    n = Math.floor(n / 7);
  }
  return (num < 0 ? "-" : "") + digits.reverse().join("");
}

