class Solution:
    def toBaseSeven(self, num: int) -> str:
        if num == 0:
            return "0"
        n = abs(num)
        digits = []
        while n:
            n, d = divmod(n, 7)
            digits.append(str(d))
        return ("-" if num < 0 else "") + "".join(reversed(digits))

